<?php require_once __DIR__.'/../includes/bootstrap.php'; if(!empty($_SESSION['user'])){header('Location: ../student/dashboard.php');exit;} $error=''; if($_SERVER['REQUEST_METHOD']==='POST'){csrf_check();$email=strtolower(trim($_POST['email']??''));$password=$_POST['password']??'';$q=$pdo->prepare('SELECT id,name,email,password_hash,role FROM users WHERE email=?');$q->execute([$email]);$user=$q->fetch();if($user&&password_verify($password,$user['password_hash'])){session_regenerate_id(true);$_SESSION['user']=['id'=>(int)$user['id'],'name'=>$user['name'],'email'=>$user['email'],'role'=>$user['role']];flash('Welcome back, '.$user['name'].'.');header('Location: ../student/dashboard.php');exit;}else $error='Invalid email or password.';} header_html('Sign In'); ?>
<div class="form-card"><h1>Sign in</h1><p class="muted">Access your student or placement administrator account.</p><?php if($error):?><div class="notice error"><?=e($error)?></div><?php endif;?><form method="post"><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><div class="field"><label>Email</label><input type="email" name="email" required autocomplete="username"></div><div class="field"><label>Password</label><input type="password" name="password" required autocomplete="current-password"></div><button type="submit">Sign in</button></form><p class="small">New student? <a href="register.php">Create an account</a></p><p class="small muted">Admin demo: create an account through the SQL instructions in README, then change its role to admin.</p></div><?php footer_html(); ?>
